package com.pulselens.analytics.controller;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(MethodArgumentNotValidException.class)@ResponseStatus(HttpStatus.BAD_REQUEST)public Map<String,Object> validation(MethodArgumentNotValidException e){return Map.of("message",e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).findFirst().orElse("Invalid request."));}@ExceptionHandler(IllegalArgumentException.class)@ResponseStatus(HttpStatus.BAD_REQUEST)public Map<String,Object> illegal(IllegalArgumentException e){return Map.of("message",Objects.toString(e.getMessage(),"Invalid request."));}@ExceptionHandler(Exception.class)@ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)public Map<String,Object> other(Exception e){return Map.of("message","Server could not complete the request. Check backend logs.");}}
